		Timer: function (tpl) {
      var self = this;
      self.tpl = tpl;
      self.startTime = 0;
      self.paused = true;
      self.msElapsed = 0;
      self.intervalId = null;

      self.el = function () {
        var activity = Lampa.Activity.active();
        if (!activity || !activity.activity) return $();
        return activity.activity.render().find(self.tpl).first();
      };

      self.tick = function () {
        var $el = self.el();
        if (!$el.length) {
          self.stop();
          return;
        }
        self.msElapsed = Date.now() - self.startTime;
        $el.text(self.formatTime(self.msElapsed));
      };

      self.start = function () {
        self.stop();
        self.paused = false;
        self.startTime = Date.now();
        self.msElapsed = 0;
        self.tick();
        self.intervalId = setInterval(self.tick, 100);
      };
      self.stop = function () {
        if (self.intervalId) {
          clearInterval(self.intervalId);
          self.intervalId = null;
        }
        self.paused = true;
        return self.formatTime(self.msElapsed);
      };
      self.formatTime = function (ms) {
        var totalSeconds = Math.floor(ms / 1000);
        var centiseconds = Math.floor((ms % 1000) / 10);
        var sec = totalSeconds < 10 ? '0' + totalSeconds : String(totalSeconds);
        var cs = centiseconds < 10 ? '0' + centiseconds : String(centiseconds);
        return sec + ':' + cs + ' c';
      };
    },
