	function migrateStorageKeys() {
		try {
			var ls = window.localStorage, old = [], i, key, next;
			for (i = 0; i < ls.length; i++) {
				key = ls.key(i);
				if (key && (key.indexOf('mods_') === 0 || key === 'showModssVip')) old.push(key);
			}
			if (!old.length) return;
			for (i = 0; i < old.length; i++) {
				key = old[i];
				next = key === 'showModssVip' ? 'modss_show_vip' : 'modss_' + key.slice(5);
				if (ls.getItem(next) === null) ls.setItem(next, ls.getItem(key));
				ls.removeItem(key);
			}
		} catch (e) {}
	}

