		function cardFilled(card) {
			return !!(card && (card.title || card.name));
		}

		Lampa.Listener.follow('full', function (e) {
			if (e.type == 'complite') {
				addButton(e.data.movie);
			}
		});
		Lampa.Listener.follow('activity', function (e) {
			if (e.component == 'full' && e.type == 'start') { 
				var button = Lampa.Activity.active().activity.render().find('.view--modss_online');
				if(button.length) {
					if (cardFilled(e.object.card)) cards = e.object.card;
					Modss.online(button);
					Modss.last_view(e.object.card);
				}
			}
		});
